  1300  HermesRuntimeImpl::prepareJavaScript(
  1301      const std::shared_ptr<const jsi::Buffer> &jsiBuffer,
  1302      std::string sourceURL) {
  1303    std::pair<std::unique_ptr<hbc::BCProvider>, std::string> bcErr{};
  1304    auto buffer = std::make_unique<BufferAdapter>(std::move(jsiBuffer));
  1305    vm::RuntimeModuleFlags runtimeFlags{};
  1306    runtimeFlags.persistent = true;
  1307
  1308    bool isBytecode = isHermesBytecode(buffer->data(), buffer->size());
  1309  #ifdef HERMESVM_PLATFORM_LOGGING
  1310    hermesLog(
  1311        "HermesVM", "Prepare JS on %s.", isBytecode ? "bytecode" : "source");
  1312  #endif
  1313    // Save the first few bytes of the buffer so that we can later append them
  1314    // to any error message.
  1315    uint8_t bufPrefix[16];
  1316    const size_t bufSize = buffer->size();
  1317    memcpy(bufPrefix, buffer->data(), std::min(sizeof(bufPrefix), bufSize));
  1318
  1319    // Construct the BC provider either from buffer or source.
  1320    if (isBytecode) {
  1321      bcErr = hbc::BCProviderFromBuffer::createBCProviderFromBuffer(
  1322          std::move(buffer));
  1323    } else {
  1324  #if defined(HERMESVM_LEAN)
  1325      bcErr.second = "prepareJavaScript source compilation not supported";
  1326  #else
  1327      bcErr = hbc::BCProviderFromSrc::createBCProviderFromSrc(
  1328          std::move(buffer), sourceURL, compileFlags_);
  1329  #endif
  1330    }
  1331    if (!bcErr.first) {
  1332      std::string storage;
  1333      llvh::raw_string_ostream os(storage);
  1334      os << " Buffer size " << bufSize << " starts with: ";
  1335      for (size_t i = 0; i < sizeof(bufPrefix) && i < bufSize; ++i)
  1336        os << llvh::format_hex_no_prefix(bufPrefix[i], 2);
  1337      LOG_EXCEPTION_CAUSE(
  1338          "Compiling JS failed: %s, %s", bcErr.second.c_str(), os.str().c_str());
  1339      throw jsi::JSINativeException(
  1340          "Compiling JS failed: " + std::move(bcErr.second) + os.str());
  1341    }
  1342    return std::make_shared<const HermesPreparedJavaScript>(
  1343        std::move(bcErr.first), runtimeFlags, std::move(sourceURL));
  1344  }
